import React, { useState } from "react";
import { motion } from "framer-motion";
import { Star } from "lucide-react";

const Feedback = () => {
  const [feedback, setFeedback] = useState("");
  const [rating, setRating] = useState(0);
  const [submitted, setSubmitted] = useState(false);

  const handleRating = (value) => setRating(value);

  const handleSubmit = (e) => {
    e.preventDefault();
    if (feedback.trim() === "" || rating === 0) return;
    setSubmitted(true);
  };

  return (
    <div className="min-h-screen bg-gradient-to-b from-blue-900 to-blue-700 flex flex-col items-center justify-center px-6 py-12 text-white">
      <motion.div
        initial={{ opacity: 0, y: -30 }}
        animate={{ opacity: 1, y: 0 }}
        transition={{ duration: 0.7 }}
        className="text-center mb-10"
      >
        <h1 className="text-4xl font-bold mb-2">We Value Your Feedback</h1>
        <p className="text-gray-200 text-lg">
          Help us improve your AI interview experience
        </p>
      </motion.div>

      {!submitted ? (
        <motion.form
          onSubmit={handleSubmit}
          initial={{ opacity: 0, y: 40 }}
          animate={{ opacity: 1, y: 0 }}
          transition={{ duration: 0.8 }}
          className="bg-white/10 backdrop-blur-lg shadow-xl rounded-2xl p-8 w-full max-w-md"
        >
          {/* Rating */}
          <div className="mb-6 text-center">
            <p className="text-lg mb-3 font-medium">Rate Your Experience</p>
            <div className="flex justify-center gap-3">
              {[1, 2, 3, 4, 5].map((num) => (
                <Star
                  key={num}
                  size={32}
                  onClick={() => handleRating(num)}
                  className={`cursor-pointer transition-transform transform hover:scale-110 ${
                    num <= rating ? "text-yellow-400 fill-yellow-400" : "text-gray-400"
                  }`}
                />
              ))}
            </div>
          </div>

          {/* Feedback Input */}
          <textarea
            value={feedback}
            onChange={(e) => setFeedback(e.target.value)}
            placeholder="Share your thoughts or suggestions..."
            className="w-full p-4 rounded-lg bg-white/20 text-white placeholder-gray-300 focus:outline-none focus:ring-2 focus:ring-yellow-400 resize-none mb-6 h-32"
          />

          {/* Additional options */}
          <div className="flex flex-col gap-3 mb-6">
            <label className="flex items-center gap-2">
              <input type="checkbox" className="accent-yellow-400" /> 
              The feedback system was easy to use.
            </label>
            <label className="flex items-center gap-2">
              <input type="checkbox" className="accent-yellow-400" /> 
              I found the AI responses accurate.
            </label>
            <label className="flex items-center gap-2">
              <input type="checkbox" className="accent-yellow-400" /> 
              I would recommend this platform to others.
            </label>
          </div>

          {/* Submit Button */}
          <motion.button
            whileHover={{ scale: 1.05 }}
            whileTap={{ scale: 0.95 }}
            type="submit"
            className="w-full py-3 bg-yellow-400 text-black font-semibold rounded-lg hover:bg-yellow-500 transition-all"
          >
            Submit Feedback
          </motion.button>
        </motion.form>
      ) : (
        <motion.div
          initial={{ opacity: 0, scale: 0.8 }}
          animate={{ opacity: 1, scale: 1 }}
          className="bg-white/10 backdrop-blur-lg shadow-xl rounded-2xl p-10 text-center"
        >
          <h2 className="text-2xl font-semibold mb-2 text-yellow-300">
            🎉 Thank You!
          </h2>
          <p className="text-gray-200 mb-6">
            Your feedback helps us build a better experience for future users.
          </p>
          <button
            onClick={() => setSubmitted(false)}
            className="px-6 py-2 bg-yellow-400 text-black rounded-lg hover:bg-yellow-500 transition-all"
          >
            Give More Feedback
          </button>
        </motion.div>
      )}
    </div>
  );
};

export default Feedback;
